```sql
SELECT SUM(Amount) AS Total_Revenue, SUM(Boxes) AS Total_Boxes FROM sales;
```

```sql
SELECT p.Category, SUM(s.Amount) AS Category_Revenue FROM sales s JOIN products p ON s.PID = p.PID GROUP BY p.Category ORDER BY Category_Revenue DESC;
```

```sql
SELECT s.SaleDate, s.Amount, s.Boxes, g.Geo FROM sales s JOIN geo g ON s.GeoID = g.GeoID WHERE s.Amount > 10000 AND g.Geo = 'India' ORDER BY s.Amount DESC;
```

```sql
SELECT p.Product, SUM(s.Amount) AS Revenue FROM sales s JOIN products p ON s.PID = p.PID WHERE s.SaleDate >= '2022-01-01' AND s.SaleDate <= '2022-12-31' GROUP BY p.Product ORDER BY Revenue DESC LIMIT 5;
```

```sql
SELECT AVG(Amount) AS Average_Order_Value FROM sales WHERE SaleDate >= '2021-01-01' AND SaleDate <= '2021-12-31';
```

```sql
SELECT p.Salesperson, p.Team, SUM(s.Boxes) AS Total_Boxes FROM sales s JOIN people p ON s.SPID = p.SPID GROUP BY p.Salesperson, p.Team ORDER BY Total_Boxes DESC LIMIT 10;
```

```sql
SELECT p.Team, SUM(s.Amount) AS Total_Sales, COUNT(s.SPID) AS Transaction_Count FROM sales s JOIN people p ON s.SPID = p.SPID GROUP BY p.Team ORDER BY Total_Sales DESC;
```

```sql
SELECT g.Geo, SUM(s.Amount) AS Revenue, SUM(s.Boxes) AS Boxes FROM sales s JOIN geo g ON s.GeoID = g.GeoID GROUP BY g.Geo ORDER BY Revenue DESC;
```
